css:
:root{
  --indigo:#2E2B3F; --cream:#FFE9DA; --oat:#F6F2EB; --sand:#E6D6C3;
  --sage:#7F8D7A; --sage-deep:#4C5A47; --terracotta:#C76B4B; --muted:#7C7784;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:#1b1a26;color:var(--indigo);font-family:Calibri,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased;overflow:hidden}
body.flow{overflow:auto;background:var(--oat)}
.serif{font-family:Georgia,"Times New Roman",serif}
h1,h2,h3{margin:0;font-family:Georgia,"Times New Roman",serif}
svg{display:block}

/* ====== STAGE (modo apresentação 1280x720) ====== */
#stage{position:absolute;left:0;top:0;width:1280px;height:720px;transform-origin:0 0}
.slide{position:absolute;inset:0;display:none;overflow:hidden;background:var(--oat)}
.slide.active{display:block}

.badge{position:absolute;right:38px;top:34px;width:77px;height:77px}
.title{position:absolute;left:58px;top:38px;width:1040px;height:86px;display:flex;align-items:center;font-size:46px;font-weight:700;color:var(--indigo)}
.body{position:absolute;left:58px;right:58px;top:150px;bottom:70px}
.foot{position:absolute;left:58px;right:58px;bottom:26px;display:flex;justify-content:space-between;font-size:13px;letter-spacing:.2em;color:var(--muted)}
.foot .pn{letter-spacing:0}

/* capa */
.slide.cover{background:var(--indigo)}
.cover .logo{position:absolute;right:84px;top:34px;width:182px}
.cover .kicker{position:absolute;left:86px;top:220px;font-size:32px;font-weight:700;color:var(--terracotta)}
.cover h1{position:absolute;left:86px;top:283px;font-size:96px;font-weight:700;color:var(--terracotta);line-height:1.1}
.cover .month{position:absolute;left:86px;top:442px;font-size:32px;color:var(--sand)}
.cover .period{position:absolute;left:86px;top:490px;font-size:19px;color:var(--sand)}
/* divisor */
.divider .dv{position:absolute;left:86px;top:264px}
.dv-num{font-size:24px;font-weight:700;letter-spacing:.22em;color:var(--terracotta);margin-bottom:6px}
.dv-title{font-size:80px;font-weight:700;color:var(--indigo);line-height:1.1}
/* encerramento */
.slide.closing{background:var(--indigo)}
.closing img{position:absolute;left:50%;top:50%;width:422px;transform:translate(-50%,-50%)}

/* ====== componentes ====== */
.card{background:#fff;border:1px solid var(--sand);border-radius:14px;box-shadow:0 4px 14px rgba(46,43,63,.08)}
.circ{border-radius:50%;background:var(--cream);display:flex;align-items:center;justify-content:center;flex:none;color:var(--indigo)}
.circ svg{width:46%;height:46%}
.grid{display:grid;gap:22px 29px}
.g2{grid-template-columns:1fr 1fr}.g3{grid-template-columns:repeat(3,1fr)}.g4{grid-template-columns:repeat(4,1fr);gap:29px 19px}

.kcard{padding:34px 34px 0;height:225px}
.k-top{display:flex;align-items:center;gap:22px}
.k-top .circ{width:67px;height:67px}
.k-label{font-size:21px;font-weight:700;color:var(--muted)}
.k-val{font-family:Georgia,serif;font-size:48px;margin-top:22px;line-height:1.1}
.k-cap{font-size:17px;color:var(--muted);margin-top:10px}
.kcard.sm{padding:28px 28px 0;height:211px}
.kcard.sm .circ{width:58px;height:58px}
.kcard.sm .k-val{font-size:32px;margin-top:34px}
.kcard.sm .k-lab{font-size:19px;color:var(--muted);margin-top:8px}
.kcard.att .k-val{color:var(--terracotta)}

/* resumo */
.obj{font-size:27px;font-weight:700;margin-top:8px}
.obj .t{color:var(--terracotta)}
.sub{font-size:21px;color:var(--muted);margin-top:30px}
.channels{display:flex;justify-content:space-around;margin-top:36px;padding:0 150px}
.ch{text-align:center;display:flex;flex-direction:column;align-items:center}
.ch .circ{width:182px;height:182px;margin-bottom:28px}
.ch b{font-size:24px}
.ch span{font-size:18px;color:var(--muted);margin-top:6px}

/* chevrons */
.chev-stage{position:relative;height:470px}
.chev-item{position:absolute;top:191px;width:288px;height:168px}
.chev-bg{position:absolute;inset:0;width:100%;height:100%}
.chev-in{position:absolute;left:calc(50% - 0px);top:0;transform:translateX(-50%);width:200px;height:168px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:4px}
.chev-item.first .chev-in{left:calc(50% - 21px)}
.chev-in .ic{width:42px;height:42px;color:var(--indigo)}
.chev-in b{font-size:21px}
.chev-in .val{font-family:Georgia,serif;font-size:24px;white-space:nowrap}
.chev-var{position:absolute;top:187px;left:0;width:100%;text-align:center;font-size:24px;font-weight:700;color:var(--muted)}
.chev-var small{display:none}
.chev-legend{position:absolute;left:10px;top:431px;font-size:16px;color:var(--muted)}
.chev-note{position:absolute;right:0;top:431px;font-size:16px;color:var(--muted)}
.brackets{position:absolute;left:0;top:0}
.b-label{position:absolute;transform:translateX(-50%);text-align:center;font-size:24px;font-weight:700;line-height:1.2}
.b-label small{display:block;font-size:16px;font-weight:400;color:var(--muted)}
.pills{display:none}

/* tabelas */
.tw{overflow-x:auto}
table.tb{border-collapse:collapse;width:100%;font-size:17px}
table.tb th{background:var(--cream);font-weight:700;border:1px solid var(--sand);padding:9px 12px;text-align:center}
table.tb td{background:#fff;border:1px solid var(--sand);padding:9px 12px;text-align:center}
table.tb th:first-child,table.tb td:first-child{text-align:left}
table.tb td.m{color:var(--muted)}
table.tb tr.tot td{background:var(--oat);font-weight:700}
.evo-wrap{height:300px}
.evo-wrap svg{width:100%;height:100%}
.evo-table{margin-top:14px}
.evo-table table.tb td,.evo-table table.tb th{padding:6px 12px}

/* retenção */
.ret{display:grid;grid-template-columns:442px 1fr;gap:29px}
.ret .col{display:flex;flex-direction:column;gap:29px}
.callout{padding:30px 30px 0;height:202px}
.callout .k-top .circ{width:58px;height:58px}
.callout .k-label{font-size:19px;color:var(--indigo);line-height:1.2}
.callout .k-label small{display:block;font-size:16px;font-weight:400;color:var(--muted)}
.callout .k-val{color:var(--terracotta);font-size:48px;margin-top:16px}
.callout .k-cap{font-size:16px;margin-top:6px}
.chart-card{padding:26px 34px;height:432px}
.chart-card h3{font-family:Calibri,"Segoe UI",sans-serif;font-size:21px;font-weight:700}
.bars{margin-top:34px;display:flex;flex-direction:column;gap:42px}
.bar-row{display:grid;grid-template-columns:96px 1fr 80px;align-items:center;gap:14px;font-size:19px}
.bar-track{height:52px;background:transparent}
.bar-fill{height:100%;background:var(--indigo)}
.bar-val{font-size:19px}

/* criativos */
.crea{display:grid;grid-template-columns:repeat(3,1fr);gap:35px}
.frame{position:relative;height:288px;background:var(--sand);border-radius:14px;display:flex;align-items:center;justify-content:center;text-align:center;color:var(--muted);font-size:19px;line-height:1.4}
.rank{position:absolute;right:-6px;top:-26px;width:72px;height:72px;border-radius:50%;background:var(--terracotta);color:#fff;font-size:24px;font-weight:700;display:flex;align-items:center;justify-content:center}
.crea table.tb{margin-top:22px}

/* perfil */
.perfil{display:flex;justify-content:space-between;margin-top:30px}
.pf{width:200px;text-align:center}
.pf .circ{width:168px;height:168px;margin:0 auto 40px}
.pf .v{font-family:Georgia,serif;font-size:40px}
.pf .c{font-size:19px;color:var(--muted);margin-top:10px}
.pre .kcard{height:250px}
.pre .k-val{font-size:56px;margin-top:34px}

/* funil */
.fun{padding:18px 36px 16px}
.fun-head,.fun-row{display:grid;grid-template-columns:300px 110px 1fr 150px 190px;align-items:center;column-gap:14px}
.fun-head{font-size:15px;font-weight:700;letter-spacing:.18em;color:var(--muted);padding-bottom:10px}
.fun-head span:nth-child(4){text-align:center}.fun-head span:nth-child(5),.fun-row .cost{text-align:right}
.fun-row{height:75px;border-top:1px solid var(--sand)}
.fun-row .lb{font-size:22px;font-weight:700}
.fun-row .nv{font-family:Georgia,serif;font-size:35px}
.fun-row .tr{height:17px;border-radius:9px;background:var(--sand);overflow:hidden}
.fun-row .fl{height:100%;border-radius:9px;background:var(--indigo);min-width:17px}
.fun-row .rt{text-align:center;font-size:22px;font-weight:700;color:var(--terracotta)}
.fun-row .cost{font-size:19px;color:var(--muted)}

/* foco */
.foco .card{height:202px;padding:30px 36px;display:flex;gap:30px}
.foco .n{font-family:Georgia,serif;font-size:53px;color:var(--terracotta);line-height:1}
.foco .tx{font-size:21px;line-height:1.35}

/* navegação */
.nav{position:fixed;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:6px;background:rgba(27,26,38,.78);border:1px solid rgba(255,233,218,.18);border-radius:99px;padding:5px 8px;color:var(--cream);font-size:14px;z-index:10;opacity:.45;transition:opacity .2s}
.nav:hover{opacity:1}
.nav button{all:unset;cursor:pointer;width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:20px;line-height:1}
.nav button:hover{background:rgba(255,233,218,.14)}
.nav .ct{min-width:58px;text-align:center}
body.flow .nav{display:none}

/* ====== MODO FLUXO (celular / telas estreitas) ====== */
body.flow #stage{position:static;width:auto;height:auto;transform:none!important}
body.flow .slide{position:relative;display:block;inset:auto;height:auto;padding:26px 18px 28px;border-bottom:10px solid var(--sand)}
body.flow .slide.cover{padding:60px 22px 56px;min-height:70vh;display:flex;flex-direction:column;justify-content:center;border-bottom:0}
body.flow .cover .logo{position:static;width:120px;margin:0 0 36px auto}
body.flow .cover .kicker,body.flow .cover h1,body.flow .cover .month,body.flow .cover .period{position:static}
body.flow .cover .kicker{font-size:20px}
body.flow .cover h1{font-size:50px;margin:6px 0 16px}
body.flow .cover .month{font-size:22px}body.flow .cover .period{font-size:14px;margin-top:6px}
body.flow .badge{position:absolute;right:16px;top:16px;width:46px;height:46px}
body.flow .title{position:static;width:auto;height:auto;font-size:28px;padding:34px 56px 16px 0;display:block;line-height:1.15}
body.flow .body{position:static}
body.flow .foot{display:none}
body.flow .slide.divider{padding:54px 22px 50px}
body.flow .divider .dv{position:static}
body.flow .dv-title{font-size:42px}body.flow .dv-num{font-size:16px}
body.flow .slide.closing{padding:60px 20px;border-bottom:0}
body.flow .closing img{position:static;width:min(300px,80%);transform:none;margin:0 auto}
body.flow .grid,body.flow .g2,body.flow .g3{grid-template-columns:1fr;gap:14px}
body.flow .g4{grid-template-columns:1fr 1fr;gap:12px}
body.flow .kcard,body.flow .kcard.sm,body.flow .callout{height:auto;padding:20px 20px 22px}
body.flow .k-val{font-size:34px;margin-top:14px}
body.flow .kcard.sm .k-val{font-size:26px;margin-top:16px}
body.flow .k-top .circ,body.flow .kcard.sm .circ{width:50px;height:50px}
body.flow .k-label{font-size:17px}
body.flow .obj{font-size:19px}body.flow .sub{font-size:16px;margin-top:14px}
body.flow .channels{flex-direction:column;gap:28px;padding:0;margin-top:22px}
body.flow .ch .circ{width:120px;height:120px;margin-bottom:14px}
body.flow .chev-stage{height:auto;display:flex;flex-direction:column;gap:10px;padding-top:6px}
body.flow .brackets,body.flow .b-label,body.flow .chev-bg{display:none}
body.flow .chev-item{position:relative;top:auto;left:auto!important;width:100%;height:auto;background:#fff;border:1px solid var(--sand);border-radius:14px;padding:14px 16px;display:flex;align-items:center;gap:14px}
body.flow .chev-in,body.flow .chev-item.first .chev-in{position:static;left:auto;transform:none;width:auto;height:auto;flex-direction:row;gap:14px;flex:1;text-align:left;justify-content:flex-start}
body.flow .chev-in .ic{width:30px;height:30px}
body.flow .chev-in b{font-size:16px;flex:1}
body.flow .chev-in .val{font-size:20px}
body.flow .chev-var{position:static;width:auto;font-size:15px}
body.flow .chev-var small{display:inline;font-weight:400}
body.flow .chev-legend,body.flow .chev-note{position:static;display:block;margin-top:6px;font-size:13px;text-align:left}
body.flow .pills{display:flex;gap:10px;flex-wrap:wrap;margin-top:6px}
body.flow .pills span{background:var(--cream);border:1px solid var(--sand);border-radius:99px;padding:6px 14px;font-size:14px;font-weight:700}
body.flow .evo-wrap{height:auto}
body.flow .evo-wrap svg{min-width:640px;height:auto}
body.flow .ret{grid-template-columns:1fr;gap:14px}
body.flow .ret .col{gap:14px}
body.flow .chart-card{height:auto;padding:20px}
body.flow .bars{gap:26px;margin-top:22px}
body.flow .bar-track{height:34px}
body.flow .bar-row{grid-template-columns:70px 1fr 56px;font-size:15px}
body.flow .crea{grid-template-columns:1fr;gap:34px}
body.flow .frame{height:200px}
body.flow .perfil{flex-wrap:wrap;gap:26px 10px;justify-content:center}
body.flow .pf{width:46%}
body.flow .pf .circ{width:110px;height:110px;margin-bottom:16px}
body.flow .pf .v{font-size:28px}body.flow .pf .c{font-size:14px}
body.flow .pre .kcard{height:auto}body.flow .pre .k-val{font-size:40px}
body.flow .fun{padding:6px 16px}
body.flow .fun-head{display:none}
body.flow .fun-row{height:auto;grid-template-columns:1fr auto;row-gap:8px;padding:14px 0}
body.flow .fun-row .lb{font-size:17px}
body.flow .fun-row .nv{font-size:26px;text-align:right}
body.flow .fun-row .tr{grid-column:1/-1}
body.flow .fun-row .rt{text-align:left;font-size:16px}
body.flow .fun-row .cost{font-size:14px}
body.flow .foco .card{height:auto;padding:20px;gap:18px}
body.flow .foco .n{font-size:36px}body.flow .foco .tx{font-size:16px}

/* ====== IMPRESSÃO ====== */
@media print{
  @page{size:1280px 720px;margin:0}
  html,body{background:#fff;overflow:visible}
  .nav{display:none}
  #stage{position:static!important;transform:none!important;width:1280px;height:auto}
  .slide{display:block!important;position:relative!important;width:1280px;height:720px;page-break-after:always;break-after:page;overflow:hidden;-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
